import { test, expect } from '@playwright/test';

test.describe('User Profile - Update Display Name', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
    await page.getByRole('button', { name: 'Login' }).click();
    await page.getByLabel('Username').fill('testuser');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Submit' }).click();
  });

  test('should update display name successfully', async ({ page }) => {
    await page.getByLabel('Display Name').fill('New Display Name');
    await page.getByRole('button', { name: 'Save Changes' }).click();

    const successMessage = await page.getByText('Display name updated successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should reflect updated display name across the app', async ({ page }) => {
    await page.getByLabel('Display Name').fill('Another Display Name');
    await page.getByRole('button', { name: 'Save Changes' }).click();

    await page.goto('/home');
    const updatedDisplayName = await page.getByText('Another Display Name');
    await expect(updatedDisplayName).toBeVisible();
  });
});
